<?php
namespace App\Domain\CaseStudies; use App\Models\CaseStudy; use Illuminate\Support\Facades\DB; final class CaseStudyRelationManager { public function sync(CaseStudy $item,array $solutions,array $products,array $industries,array $capabilities,array $pages):void{DB::transaction(function()use($item,$solutions,$products,$industries,$capabilities,$pages){foreach(['relatedSolutions'=>$solutions,'relatedProducts'=>$products,'relatedIndustries'=>$industries,'relatedCapabilities'=>$capabilities,'relatedPages'=>$pages] as $relation=>$ids){$item->{$relation}()->sync(collect($ids)->values()->mapWithKeys(fn($id,$order)=>[$id=>['display_order'=>$order]])->all());}});CaseStudyCache::forget($item->id);} }
